def build_frozen_transfer(source, data):
    encoder = copy.deepcopy(source.encoder)
    for parameter in encoder.parameters():
        parameter.requires_grad = False
    seed_all()
    return train_classifier(TargetModel(encoder), data["target_X"], data["target_y"], epochs=200, lr=0.2)

def fine_tune(frozen_model, data, *, lr: float = 0.01):
    model = copy.deepcopy(frozen_model)
    for parameter in model.encoder.parameters():
        parameter.requires_grad = True
    return train_classifier(model, data["target_X"], data["target_y"], epochs=80, lr=lr)
